<section class="card"><div class="section-heading"><div><h2>Dấu vết hoạt động</h2><p class="muted">Tối đa 200 sự kiện mới nhất theo bộ lọc.</p></div><span class="badge active">AUDIT LOG</span></div><form method="get" class="filter-form" id="audit-filter"><div><?php field('username','Tên đăng nhập',$username,'text',64,false) ?></div><div><?php field('action','Hành động',$action,'text',64,false) ?></div><button id="filter-audit" class="button">Lọc nhật ký</button><a href="/admin/audit">Đặt lại</a></form><div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Tài khoản</th><th>Hành động</th><th>Đối tượng</th><th>IP nguồn</th><th>Kết quả</th></tr></thead><tbody><?php foreach($list as $log): ?><tr><td class="muted"><?= e($log['thoi_gian']) ?></td><td><?= e($log['username']) ?></td><td class="mono"><?= e($log['hanh_dong']) ?></td><td><?= e($log['doi_tuong']) ?></td><td class="mono"><?= e($log['ip_nguon']) ?></td><td><span class="badge <?= $log['ket_qua']==='success'?'active':'locked' ?>"><?= e($log['ket_qua']) ?></span></td></tr><?php endforeach ?><?php if(!$list): ?><tr><td colspan="6" class="empty">Không có sự kiện phù hợp.</td></tr><?php endif ?></tbody></table></div></section>
